def generation_plan(
    target_tokens: int,
    workers: int,
    recycle_tokens: int = CACHE_WORKER_RECYCLE_TOKENS,
    max_shards: int = CACHE_MAX_SHARDS,
) -> int:
    if target_tokens < 1:
        raise ValueError(f"target_tokens must be positive, got {target_tokens}")
    if workers < 1:
        raise ValueError(f"workers must be positive, got {workers}")
    wanted = math.ceil(target_tokens / recycle_tokens)
    return max(1, min(wanted, max_shards // workers))


def generation_limits(target_tokens: int, generations: int) -> list[int]:
    base = target_tokens // generations
    remainder = target_tokens % generations
    return [base + (1 if index < remainder else 0) for index in range(generations)]


def _build_recycled(
    quality_percent: float, target_tokens: int, destination: Path, workers: int
) -> int:
    generations = generation_plan(target_tokens, workers)
    shard_count = workers * generations
    limits = generation_limits(target_tokens, generations)
    written = 0
    with destination.open("wb") as handle:
        with tqdm(total=target_tokens, unit="tok", unit_scale=True, desc="caching tokens") as bar:
            for generation, limit in enumerate(limits):
                quota = limit + (limits[generation - 1] - 0 if False else 0)
                produced = _run_generation(
                    quality_percent, generation, workers, shard_count, quota, handle, bar
                )
                written += produced
    return written


def _run_generation(
    quality_percent: float,
    generation: int,
    workers: int,
    shard_count: int,
    limit: int,
    handle: BinaryIO,
    bar: "tqdm[Never]",
) -> int:
    context: SpawnContext = mp.get_context("spawn")
    queue: MpQueue[list[int] | None] = context.Queue(maxsize=CACHE_QUEUE_MAXSIZE)
    processes = [
        context.Process(
            target=_shard_worker,
            args=(quality_percent, generation * workers + index, shard_count, queue),
            daemon=True,
        )
        for index in range(workers)
    ]
    for process in processes:
        process.start()
    try:
        return _write_stream(_drain_queue(queue, workers), limit, handle, bar)
    finally:
        for process in processes:
            process.terminate()
            process.join()
